<script setup lang="ts">
import {onMounted,ref,computed} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import * as api from '@/api/device';import {getCategories} from '@/api/category';import {getLabs} from '@/api/lab';import type {Device,DeviceForm} from '@/types/device';import type {DeviceCategory} from '@/types/category';import type {Lab} from '@/types/lab';import {formatCurrency,getStatusTagType} from '@/utils/format'
const rows=ref<Device[]>([]),cats=ref<DeviceCategory[]>([]),labs=ref<Lab[]>([]),q=ref(''),status=ref(''),loading=ref(false),dialog=ref(false),editing=ref(false),form=ref<DeviceForm>({deviceName:'',categoryId:undefined,labId:undefined,deviceSpec:'',deviceStatus:'正常',buyDate:'',price:undefined});const filtered=computed(()=>rows.value.filter(x=>(!q.value||x.deviceName.includes(q.value))&&(!status.value||x.deviceStatus===status.value)));async function load(){loading.value=true;try{[rows.value,cats.value,labs.value]=await Promise.all([api.getDevices(),getCategories(),getLabs()])}finally{loading.value=false}}function open(row?:Device){editing.value=!!row;form.value=row?{deviceName:row.deviceName,categoryId:row.categoryId,labId:row.labId,deviceSpec:row.deviceSpec,deviceStatus:row.deviceStatus,buyDate:row.buyDate,price:row.price}:{deviceName:'',categoryId:undefined,labId:undefined,deviceSpec:'',deviceStatus:'正常',buyDate:'',price:undefined};dialog.value=true}async function save(){if(!form.value.deviceName||form.value.categoryId===undefined||form.value.labId===undefined||!form.value.buyDate||form.value.price===undefined)return ElMessage.warning('请完整填写必填字段');const id=editing.value?rows.value.find(x=>x.deviceName===form.value.deviceName)?.deviceId||0:0;const ok=editing.value?await api.updateDevice(id,form.value):await api.createDevice(form.value);if(ok!==false){ElMessage.success('保存成功');dialog.value=false;load()}}async function remove(row:Device){await ElMessageBox.confirm(`确定删除“${row.deviceName}”吗？`,'提示',{type:'warning'});if(await api.deleteDevice(row.deviceId)){ElMessage.success('删除成功');load()}}onMounted(load)
</script>
<template><div class="page"><div class="page-header"><h2>设备管理</h2><el-button type="primary" @click="open()">新增设备</el-button></div><div class="card"><div class="filters"><el-input v-model="q" clearable placeholder="设备名称" style="max-width:220px"/><el-select v-model="status" clearable placeholder="设备状态" style="width:160px"><el-option v-for="x in ['正常','维修中','报废','闲置']" :key="x" :label="x" :value="x"/></el-select></div><el-table :data="filtered" v-loading="loading" empty-text="暂无数据"><el-table-column prop="deviceName" label="设备名称"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="labName" label="实验室"/><el-table-column prop="deviceStatus" label="状态"><template #default="{row}"><el-tag :type="getStatusTagType(row.deviceStatus)">{{row.deviceStatus}}</el-tag></template></el-table-column><el-table-column prop="buyDate" label="购买日期"/><el-table-column label="价格"><template #default="{row}">{{formatCurrency(row.price)}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑设备':'新增设备'" width="560px"><el-form label-width="90px"><el-form-item label="设备名称"><el-input v-model="form.deviceName"/></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId"><el-option v-for="x in cats" :key="x.categoryId" :label="x.categoryName" :value="x.categoryId"/></el-select></el-form-item><el-form-item label="实验室"><el-select v-model="form.labId"><el-option v-for="x in labs" :key="x.labId" :label="x.labName" :value="x.labId"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.deviceStatus"><el-option v-for="x in ['正常','维修中','报废','闲置']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="购买日期"><el-date-picker v-model="form.buyDate" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="价格"><el-input-number v-model="form.price" :min="0"/></el-form-item><el-form-item label="规格"><el-input v-model="form.deviceSpec" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
